import os
import torch
import random
import numpy as np


class Config:
    """
    Configuration for the Text Normalization Task.
    Implements settings for the 'Strict-Priority Hybrid Cascade with Heterogeneous Granularity'.
    """

    # ==========================================
    # Paths and Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Working directory for Idea 5 (Heterogeneous Granularity)
    WORKING_DIR = "./working/idea_5"
    SUBMISSION_DIR = "./submission"

    # Metadata File Paths (Generated by metadata script)
    TRAIN_FILE = os.path.join(METADATA_DIR, "train.csv")
    VAL_FILE = os.path.join(METADATA_DIR, "val.csv")
    TEST_FILE = os.path.join(METADATA_DIR, "test.csv")

    # Submission Output
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Cache Directories for deterministic processing
    HFBB_CACHE_DIR = os.path.join(WORKING_DIR, "hfbb_cache")
    TRANSFORMER_CACHE_DIR = os.path.join(WORKING_DIR, "transformer_cache")

    # Model Artifacts
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "transformer_best.pth")

    # Tokenizer Paths
    # Prefix for SentencePiece BPE model (will generate .model and .vocab)
    BPE_MODEL_PREFIX = os.path.join(WORKING_DIR, "bpe_ru_target")
    # Path to save character vocabulary
    VOCAB_PATH = os.path.join(WORKING_DIR, "vocab.json")

    # ==========================================
    # Data Processing Parameters
    # ==========================================
    # Classes handled by Tier 2 (Neural Network) - Semiotic/Ambiguous tokens
    SEMIOTIC_CLASSES = [
        "CARDINAL",
        "DATE",
        "MEASURE",
        "ORDINAL",
        "DECIMAL",
        "MONEY",
        "TELEPHONE",
        "ELECTRONIC",
        "DIGIT",
        "TIME",
        "FRACTION",
        "ADDRESS",
        "LETTERS",
    ]

    # Classes to Upsample in the training set to address class imbalance
    UPSAMPLE_CLASSES = [
        "MONEY",
        "DECIMAL",
        "MEASURE",
        "ORDINAL",
        "TELEPHONE",
        "ELECTRONIC",
        "FRACTION",
        "TIME",
    ]
    # Target count matches roughly the frequency of the dominant DATE class (~130k)
    UPSAMPLE_TARGET_COUNT = 130000

    # Context Window for Neural Input
    CONTEXT_WINDOW = 1  # 1 word before, 1 word after

    # ==========================================
    # Model Architecture (Heterogeneous Transformer)
    # ==========================================
    # Encoder (Character Level) - Parses symbols/digits
    ENC_EMB_DIM = 256
    ENC_HIDDEN_DIM = 512
    ENC_LAYERS = 4
    ENC_HEADS = 8

    # Decoder (Subword/BPE Level) - Generates Russian text
    DEC_EMB_DIM = 256
    DEC_HIDDEN_DIM = 512
    DEC_LAYERS = 4
    DEC_HEADS = 8

    DROPOUT = 0.1
    MAX_SEQ_LEN = 128  # Max characters for input, max subwords for output

    # Vocabulary Sizes
    BPE_VOCAB_SIZE = 8000

    # Special Tokens
    PAD_TOKEN = "<pad>"
    UNK_TOKEN = "<unk>"
    SOS_TOKEN = "<s>"
    EOS_TOKEN = "</s>"
    SEP_TOKEN = "<sep>"

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    BATCH_SIZE = 128
    LEARNING_RATE = 5e-4
    EPOCHS = 15
    PATIENCE = 3  # Early stopping patience
    LABEL_SMOOTHING = 0.1
    WEIGHT_DECAY = 1e-2
    CLIP_GRAD = 1.0
    NUM_WORKERS = 4  # For dataloaders

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup_directories(cls):
        """Creates the necessary working directory structure."""
        dirs = [
            cls.WORKING_DIR,
            cls.SUBMISSION_DIR,
            cls.HFBB_CACHE_DIR,
            cls.TRANSFORMER_CACHE_DIR,
        ]
        for d in dirs:
            os.makedirs(d, exist_ok=True)


def seed_everything(seed=42):
    """Sets the random seed for reproducibility across libraries."""
    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
